<?php declare(strict_types=1);
if($readonly||(!in_array($raw['operation'],['return','return_attach'],true)&&!isset($raw['data']['return_allocations'])))return;
$funding=$sepaState['return_funding'];$chosen=$raw['data']['return_allocations']??[];$pageIds=array_column($funding['rows']??[],'allocation_id');
?>
<section class="card" data-sepa-return-funding><h3><?=e($snt('Einzugszahlungen zuordnen'))?></h3>
<p><?=e($snt('Die tatsächlichen ursprünglichen Zahlungszuordnungen dieses Beitragsbelegs auswählen. Ihre Summe muss genau dem zurückgegebenen Einzugsbetrag entsprechen. Die Belege bleiben gültig; nur diese Beträge werden wieder offen. Gebühren separat erfassen.'))?></p>
<button class="btn btn-outline theme-secondary" name="sepa_intent" value="selection"><?=e($snt('Ursprüngliche Einzugszahlungen anzeigen'))?></button>
<?php if($chosen):?><h4><?=e($snt('Ausgewählte ursprüngliche Einzugszuordnungen'))?></h4><ul><?php foreach($chosen as$id):$choice=$sepaState['return_funding_selected'][$id]??null;?><li data-sepa-return-funding-selected="<?=e($id)?>"><?php if(!in_array($id,$pageIds,true))echo hidden('sepa_return_allocations[]',$id);?><?php if($choice):?><?=e(dateDe($choice['booked_on']).' · '.$choice['account_name'].' · '.euro((int)$choice['cents']).' · '.$choice['description'])?> <a class="btn btn-outline theme-secondary" href="<?=e(url(bankTransactionContext($choice['transaction_id'],$_GET)))?>" target="_blank" rel="noopener"><?=e($snt('Tatsächliche ursprüngliche Zahlung öffnen'))?></a><?php else:?><pre><?=e($id)?></pre><?php endif ?></li><?php endforeach?></ul><button class="btn btn-outline theme-secondary" name="sepa_intent" value="clear-funding"><?=e($snt('Auswahl ursprünglicher Einzugszahlungen leeren'))?></button><?php endif?>
<label><?=e($snt('Ursprüngliche Einzugszahlung suchen'))?><?php $snfield('sepa_return_allocation_q',$snraw($_POST,'sepa_return_allocation_q'),false);?></label><button class="btn btn-outline theme-secondary" name="sepa_intent" value="selection"><?=e($snt('Ganze ursprüngliche Zahlungssuche anzeigen'))?></button>
<?php foreach($funding['rows']??[]as$source):?><label class="general-settings-check" data-sepa-return-funding-choice="<?=e($source['allocation_id'])?>"><input class="check" type="checkbox" name="sepa_return_allocations[]" value="<?=e($source['allocation_id'])?>"<?=in_array($source['allocation_id'],$chosen,true)?' checked':''?>><span><?=e(dateDe($source['booked_on']).' · '.$source['account_name'].' · '.euro((int)$source['cents']))?><br><?=e($source['description'].' · '.$source['counterparty'])?></span></label><?php endforeach?>
<?php if($funding):?><p><?=e(strtr($snt('Seite {page} von {pages}'),['{page}'=>(string)$funding['page'],'{pages}'=>(string)$funding['pages']]))?> · <?=(int)$funding['total']?></p><?php if(!$funding['rows']):?><p><?=e($snt('Keine vollständig verfügbare ursprüngliche Einzugszuordnung gefunden. Ursprüngliche Zahlung und Suchangaben prüfen.'))?></p><?php endif?><?php endif?>
<label><?=e($snt('Seite der ursprünglichen Einzugszahlungen'))?><?php $snfield('sepa_return_allocation_page',$snraw($_POST,'sepa_return_allocation_page','1'),false);?></label><button class="btn btn-outline theme-secondary" name="sepa_intent" value="selection"><?=e($snt('Seite der ursprünglichen Einzugszahlungen anzeigen'))?></button>
<p><?=e($snt('Eine bis vierzig ursprüngliche Zuordnungen sind möglich, auch aus einer gemeinsam gebuchten Zahlung. Eine einzige vollständig eindeutige und ungeteilte Einzugszahlung kann weiterhin über den bisherigen vollständigen Rücklastschriftweg geprüft werden.'))?></p>
